B.a_K=s(["\u0645\u0642\u062f\u0645\u0648 \u0627\u0644\u062e\u062f\u0645\u0629 \u0645\u0633\u062a\u0642\u0644\u0648\u0646 \u0639\u0646 \u0627\u0644\u0645\u0627\u0644\u0643 \u0648\u0641\u0631\u064a\u0642 \u0627\u0644\u0639\u0645\u0644. \u0644\u064a\u0633\u0648\u0627 \u0645\u0648\u0638\u0641\u064a\u0646 \u0648\u0644\u0627 \u0648\u0643\u0644\u0627\u0621 \u0648\u0644\u0627 \u0645\u0645\u062b\u0644\u064a\u0646 \u0644\u0644\u062a\u0637\u0628\u064a\u0642. \u0623\u0642\u0648\u0627\u0644\u0647\u0645 \u0648\u0648\u0639\u0648\u062f\u0647\u0645 \u0648\u0627\u0644\u062a\u0632\u0627\u0645\u0627\u062a\u0647\u0645 \u062a\u062e\u0635\u0647\u0645 \u0648\u062d\u062f\u0647\u0645\u060c \u0648\u0644\u0627 \u062a\u064f\u0646\u0633\u0628 \u0625\u0644\u0649 \u0645\u0627\u0644\u0643 \u0627\u0644\u062a\u0637\u0628\u064a\u0642."],t.s)
