B.Wz=s(["\u0644\u0627 \u064a\u0636\u0645\u0646 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u062a\u0648\u0641\u0631 \u062d\u0631\u0641\u064a \u0641\u064a \u0627\u0644\u0648\u0642\u062a \u0627\u0644\u0645\u0637\u0644\u0648\u0628\u060c \u0648\u0644\u0627 \u0645\u0647\u0627\u0631\u0629 \u0645\u0639\u064a\u0646\u0629\u060c \u0648\u0644\u0627 \u0646\u062a\u064a\u062c\u0629 \u0627\u0644\u0625\u0635\u0644\u0627\u062d\u060c \u0648\u0644\u0627 \u0633\u0644\u0627\u0645\u0629 \u0627\u0644\u0645\u0631\u0643\u0628\u0629 \u0623\u0648 \u0627\u0644\u0645\u0648\u0642\u0639\u060c \u0648\u0644\u0627 \u062f\u0642\u0629 \u0645\u0627 \u064a\u0643\u062a\u0628\u0647 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u0648\u0646 \u0645\u0646 \u062a\u0642\u064a\u064a\u0645\u0627\u062a \u0623\u0648 \u0623\u0648\u0635\u0627\u0641.","\u062a\u064f\u0642\u062f\u0651\u064e\u0645 \u0627\u0644\u0645\u0646\u0635\u0629 \u0628\u062d\u0627\u0644\u062a\u0647\u0627 \u0627\u0644\u0645\u062a\u0627\u062d\u0629 \u062e\u0644\u0627\u0644 \u0627\u0644\u062c\u0644\u0633\u0629. \u0627\u0646\u0642\u0637\u0627\u0639 \u0627\u0644\u062a\u062c\u0631\u0628\u0629 \u0623\u0648 \u0646\u0642\u0635 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u062a\u062c\u0631\u064a\u0628\u064a\u0629 \u0644\u0627 \u064a\u0631\u062a\u0628 \u062a\u0639\u0648\u064a\u0636\u0627\u064b."],t.s)
B.a8b=new A.h6("\u0639\u062f\u0645 \u0627\u0644\u0636\u0645\u0627\u0646",B.Wz)
B.a2b=s(["\u0631\u0633\u0648\u0645 \u0627\u0644\u0627\u0634\u062a\u0631\u0627\u0643 \u0645\u0642\u0627\u0628\u0644 \u0625\u062a\u0627\u062d\u0629 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u0645\u0646\u0635\u0629\u060c \u0648\u0644\u064a\u0633\u062a \u0623\u062c\u0631\u0629 \u0627\u0644\u0625\u0635\u0644\u0627\u062d \u0648\u0644\u0627 \u0639\u0645\u0648\u0644\u0629 \u0639\u0644\u0649 \u0627\u0644\u0639\u0645\u0644. \u0631\u0633\u0648\u0645 \u0627\u0644\u062d\u0631\u0641\u064a \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u0646\u0633\u062e\u0629: 100 \u0631\u064a\u0627\u0644 \u0633\u0646\u0648\u064a\u0627\u064b. \u0631\u0633\u0648\u0645 \u0627\u0644\u0639\u0645\u064a\u0644: 20 \u0631\u064a\u0627\u0644\u0627\u064b \u0644\u0644\u0634\u0647\u0631\u060c \u064840 \u0631\u064a\u0627\u0644\u0627\u064b \u0644\u062b\u0644\u0627\u062b\u0629 \u0623\u0634\u0647\u0631\u060c \u064870 \u0631\u064a\u0627\u0644\u0627\u064b \u0644\u0633\u062a\u0629 \u0623\u0634\u0647\u0631\u060c \u0648120 \u0631\u064a\u0627\u0644\u0627\u064b \u0644\u0627\u062b\u0646\u064a \u0639\u0634\u0631 \u0634\u0647\u0631\u0627\u064b.","\u0627\u0644\u0633\u062f\u0627\u062f \u0627\u0644\u0638\u0627\u0647\u0631 \u0641\u064a \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0645\u062d\u0627\u0643\u0627\u0629 \u062f\u0627\u062e\u0644 \u0627\u0644\u062c\u0644\u0633\u0629. \u0644\u0627 \u062a\u064f\u062e\u0635\u0645 \u0645\u0628\u0627\u0644\u063a \u062d\u0642\u064a\u0642\u064a\u0629\u060c \u0648\u0644\u0627 \u062a\u0648\u062c\u062f \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u0646\u0633\u062e\u0629 \u0628\u0648\u0627\u0628\u0629 \u062f\u0641\u0639 \u0628\u0646\u0643\u064a\u0629."],t.s)
B.a8e=new A.h6("\u0631\u0633\u0648\u0645 \u0627\u0644\u0627\u0634\u062a\u0631\u0627\u0643",B.a2b)
B.a_6=s(["\u062a\u0628\u0642\u0649 \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u062c\u0644\u0633\u0629 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u062c\u0647\u0627\u0632 \u0641\u0642\u0637: \u0627\u0644\u0645\u062f\u064a\u0646\u0629\u060c \u0648\u0623\u0631\u0642\u0627\u0645 \u0627\u0644\u062c\u0648\u0627\u0644 \u0627\u0644\u062a\u064a \u062a\u064f\u062f\u062e\u0644\u0647\u0627\u060c \u0648\u0648\u0635\u0641 \u0627\u0644\u0637\u0644\u0628\u060c \u0648\u0627\u0644\u062a\u0642\u064a\u064a\u0645\u060c \u0648\u0631\u0633\u0627\u0626\u0644 \u0644\u0648\u062d\u0629 \u0627\u0644\u0645\u0627\u0644\u0643 \u0627\u0644\u062a\u062c\u0631\u064a\u0628\u064a\u0629. \u0644\u0627 \u064a\u064f\u0631\u0628\u0637 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0628\u062e\u0627\u062f\u0645\u060c \u0648\u0644\u0627 \u0628\u0640 Firebase\u060c \u0648\u0644\u0627 \u062a\u064f\u0628\u0627\u0639 \u0647\u0630\u0647 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a.","\u0625\u063a\u0644\u0627\u0642 \u0627\u0644\u062c\u0644\u0633\u0629 \u064a\u0632\u064a\u0644 \u0645\u0627 \u0623\u064f\u062f\u062e\u0644 \u062e\u0644\u0627\u0644\u0647\u0627. \u0644\u0627 \u062a\u064f\u0639\u0627\u0645\u0644 \u0647\u0630\u0647 \u0627\u0644\u0646\u0633\u062e\u0629 \u0639\u0644\u0649 \u0623\u0646\u0647\u0627 \u0633\u062c\u0644 \u0642\u0627\u0646\u0648\u0646\u064a \u0645\u062d\u0641\u0648\u0638 \u0644\u062f\u0649 \u0627\u0644\u0645\u0627\u0644\u0643."],t.s)
B.a88=new A.h6("\u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u0646\u0633\u062e\u0629",B.a_6)
